import { assert, describe, it } from "@effect/vitest";
import type {
  CopilotSession,
  MessageOptions,
  SessionConfig,
  SessionEvent,
} from "@github/copilot-sdk";
import {
  DEFAULT_SERVER_SETTINGS,
  MessageId,
  NodeId,
  ProjectId,
  ProviderInstanceId,
  ProviderSessionId,
  RunAttemptId,
  RunId,
  ThreadId,
  type OrchestrationV2AppThread,
  type ModelSelection,
} from "@t3tools/contracts";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Exit from "effect/Exit";
import * as Fiber from "effect/Fiber";
import * as Queue from "effect/Queue";
import * as Schema from "effect/Schema";
import * as Stream from "effect/Stream";
import * as ProviderAdapter from "@t3tools/provider-core/server/ProviderAdapter";
import * as ProviderHost from "@t3tools/provider-core/server/ProviderHost";
import * as McpProviderSessions from "@t3tools/provider-core/server/McpProviderSessions";
import { CopilotSettings } from "../settings.ts";
import { makeAdapter, type ClientHandle, type SessionHandle } from "./adapter.ts";
import type { ModelCatalog } from "./routing.ts";

const threadId = ThreadId.make("copilot-test");
const instanceId = ProviderInstanceId.make("githubCopilot");
const sessionId = ProviderSessionId.make("copilot-runtime");
const selection = { instanceId, model: "gpt-4.1", options: [] };
const policy: ProviderAdapter.ProviderAdapterV2RuntimePolicy = {
  cwd: "/workspace",
  runtimeMode: "approval-required",
  interactionMode: "default",
};
const settings = Schema.decodeSync(CopilotSettings)({});
const host = ProviderHost.ProviderHost.of({
  paths: {
    cwd: "/workspace",
    baseDir: "/test",
    stateDir: "/test/state",
    providerStatusCacheDir: "/test/cache",
    attachmentsDir: "/test/attachments",
  },
  settings: {
    get: Effect.succeed(DEFAULT_SERVER_SETTINGS),
    withSnapshot: (use) => use(DEFAULT_SERVER_SETTINGS),
    changes: Stream.empty,
    subscribe: Effect.succeed(Stream.empty),
  },
  shouldRunBackgroundWork: () => Effect.succeed(false),
  resolveAttachmentPath: (attachment) => `/test/attachments/${attachment.id}`,
  credentials: () =>
    Effect.succeed({
      binding: { owner: "t3", key: "test" },
      get: Effect.succeedNone,
      set: () => Effect.void,
      remove: Effect.void,
    }),
});

function fakeSdk() {
  let config: SessionConfig | undefined;
  let serial = 0;
  let disconnected = 0;
  let stopped = 0;
  let resumed: string | undefined;
  let conflict = false;
  let continuePendingWork: boolean | undefined;
  const permissionReplies: Array<
    Parameters<CopilotSession["rpc"]["permissions"]["handlePendingPermissionRequest"]>[0]
  > = [];
  let permissionResponse = async (): Promise<{ success: boolean }> => ({ success: true });
  let background: Awaited<ReturnType<SessionHandle["rpc"]["tasks"]["list"]>> = { tasks: [] };
  let catalog: ModelCatalog = { models: [] };
  let current: Awaited<ReturnType<SessionHandle["rpc"]["model"]["getCurrent"]>> = {
    modelId: "gpt-4.1",
  };
  const modelChanges: Array<{ model: string; options: Parameters<SessionHandle["setModel"]>[1] }> =
    [];
  const sent: MessageOptions[] = [];
  const emit = (
    type: SessionEvent["type"],
    data: unknown = {},
    agentId?: string,
    timestamp = "2026-10-29T00:00:00Z",
  ) => {
    config?.onEvent?.({
      type,
      data,
      id: `native-event-${++serial}`,
      timestamp,
      parentId: null,
      ...(agentId ? { agentId } : {}),
    } as SessionEvent);
  };
  const session: SessionHandle = {
    sessionId: "native-copilot",
    send: async (message) => {
      sent.push(typeof message === "string" ? { prompt: message } : message);
      return "native-user-message";
    },
    abort: async () => {
      emit("session.idle");
    },
    disconnect: async () => {
      disconnected++;
    },
    getEvents: async () => [],
    setModel: async (model, options) => {
      modelChanges.push({ model, options });
    },
    rpc: {
      model: {
        list: async () => ({ list: [], ...(catalog.auto ? { auto: catalog.auto } : {}) }),
        getCurrent: async () => current,
      },
      mode: { set: async () => ({ status: "success", modelChanged: false, modeApplied: true }) },
      plan: {
        read: async () => ({
          exists: true,
          content: "# Plan\n\nImplement safely",
          path: "/copilot/plan.md",
        }),
      },
      skills: { list: async () => ({ skills: [] }) },
      tasks: { list: async () => background, cancel: async () => ({ cancelled: true }) },
      permissions: {
        handlePendingPermissionRequest: async (
          response: Parameters<
            CopilotSession["rpc"]["permissions"]["handlePendingPermissionRequest"]
          >[0],
        ) => {
          permissionReplies.push(response);
          return permissionResponse();
        },
      },
    },
  };
  const client: ClientHandle = {
    rpc: { models: { list: async () => catalog } },
    start: async () => {},
    stop: async () => {
      stopped++;
      return [];
    },
    forceStop: async () => {},
    createSession: async (created) => {
      config = created;
      emit("session.idle");
      return session;
    },
    resumeSession: async (id, created) => {
      resumed = id;
      continuePendingWork = created.continuePendingWork;
      config = created;
      emit("session.resume", { alreadyInUse: conflict });
      return session;
    },
  };
  return {
    client,
    session,
    sent,
    emit,
    modelChanges,
    setCatalog: (value: ModelCatalog) => {
      catalog = value;
    },
    setCurrent: (value: typeof current) => {
      current = value;
    },
    get config() {
      return config!;
    },
    get resumed() {
      return resumed;
    },
    get continuePendingWork() {
      return continuePendingWork;
    },
    get disconnected() {
      return disconnected;
    },
    get stopped() {
      return stopped;
    },
    conflict: () => {
      conflict = true;
    },
    setTasks: (tasks: typeof background) => {
      background = tasks;
    },
    permissionReplies,
    setPermissionResponse: (response: () => Promise<{ success: boolean }>) => {
      permissionResponse = response;
    },
  };
}
type Fake = ReturnType<typeof fakeSdk>;
const durablePhase = (phaseId: string): SessionEvent => ({
  type: "assistant.fusion_phase_completed",
  id: `durable-${phaseId}`,
  timestamp: "2026-10-29T00:00:02Z",
  parentId: null,
  data: {
    fusionId: "fusion-1",
    phaseId,
    model: "model",
    role: "primary",
    phaseKind: "primary",
    conversationScope: "root",
    durationMs: 2000,
    status: "succeeded",
    content: "PRIVATE",
    verdict: null,
    usage: { inputTokens: 10, outputTokens: 5, cachedTokens: 0, requestCount: 1, totalNanoAiu: 0 },
  },
});

function promiseGate() {
  let resolve!: () => void;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

const setup = Effect.fnUntraced(function* (
  fake: Fake,
  initialNativeThreadId?: string,
  initialSelection: ModelSelection = selection,
  runtimeSessionId = sessionId,
) {
  const adapter = yield* makeAdapter(
    { instanceId, settings, environment: { HOME: "/test-account" } },
    { clientFactory: () => fake.client },
  );
  const runtime = yield* adapter.openSession({
    threadId,
    providerSessionId: runtimeSessionId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
    ...(initialNativeThreadId ? { initialNativeThreadId } : {}),
  });
  const emitted: ProviderAdapter.ProviderAdapterV2Event[] = [];
  const eventQueue = yield* Queue.unbounded<ProviderAdapter.ProviderAdapterV2Event>();
  yield* runtime.events.pipe(
    Stream.runForEach((event) =>
      Effect.sync(() => {
        emitted.push(event);
      }).pipe(Effect.andThen(Queue.offer(eventQueue, event))),
    ),
    Effect.forkScoped,
  );
  const takeEvent = Effect.fnUntraced(function* (
    predicate: (event: ProviderAdapter.ProviderAdapterV2Event) => boolean,
  ) {
    while (true) {
      const event = yield* Queue.take(eventQueue);
      if (predicate(event)) return event;
    }
  });
  const thread = yield* runtime.ensureThread({
    threadId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
  });
  const start = Effect.fnUntraced(function* (ordinal = 1, turnSelection = initialSelection) {
    const now = yield* DateTime.now;
    const appThread: OrchestrationV2AppThread = {
      id: threadId,
      projectId: ProjectId.make("project"),
      title: "Test",
      providerInstanceId: instanceId,
      modelSelection: turnSelection,
      runtimeMode: policy.runtimeMode,
      interactionMode: "default",
      branch: null,
      worktreePath: null,
      activeProviderThreadId: thread.id,
      lineage: { parentThreadId: null, relationshipToParent: null, rootThreadId: threadId },
      forkedFrom: null,
      createdBy: "user",
      creationSource: "web",
      createdAt: now,
      updatedAt: now,
      archivedAt: null,
      settledOverride: null,
      settledAt: null,
      lastVisitedAt: null,
      deletedAt: null,
    };
    yield* runtime.startTurn({
      appThread,
      threadId,
      runId: RunId.make(`run-${ordinal}`),
      runOrdinal: ordinal,
      providerTurnOrdinal: ordinal,
      attemptId: RunAttemptId.make(`attempt-${ordinal}`),
      rootNodeId: NodeId.make(`root-${ordinal}`),
      providerThread: thread,
      message: {
        messageId: MessageId.make(`user-${ordinal}`),
        text: "Hello",
        attachments: [],
        createdBy: "user",
        creationSource: "web",
      },
      modelSelection: turnSelection,
      runtimePolicy: policy,
    });
  });
  const drain = () => runtime.readThreadSnapshot({ providerThread: thread });
  return { runtime, thread, emitted, start, drain, takeEvent };
});

const provide = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
  effect.pipe(
    Effect.provideService(ProviderHost.ProviderHost, host),
    Effect.provide(McpProviderSessions.layer),
    Effect.scoped,
  );

describe("native Copilot V2", () => {
  it.effect(
    "bounds live phase records and exposes an overflow gap instead of silently losing telemetry",
    () =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const { start, emitted, takeEvent } = yield* setup(fake);
          yield* start();
          fake.emit("assistant.turn_start", { turnId: "0" });
          fake.emit("session.fusion_resolved", {
            fusionId: "fusion-1",
            turnId: "0",
            contractVersion: 1,
            pattern: "single",
            primaryModel: "model",
            fallbackModel: "model",
            syntheticModel: "auto",
          });
          for (let index = 0; index < 130; index++)
            fake.emit("assistant.fusion_phase_started", {
              fusionId: "fusion-1",
              phaseId: `phase-${index}`,
              model: "model",
              role: "primary",
              pattern: "single",
            });
          yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.kind === "gap" &&
              event.turnItem.modelExecution.phaseId === "phase-129",
          );
          const items = new Map(
            emitted.flatMap((event) =>
              event.type === "turn_item.updated"
                ? [[event.turnItem.id, event.turnItem] as const]
                : [],
            ),
          );
          assert.equal(items.size, 128);
          assert.isTrue(
            [...items.values()].some(
              (item) =>
                item.type === "system_notice" &&
                item.modelExecution?.gaps.some((gap) => gap.includes("per-turn limit")),
            ),
          );
        }),
      ),
  );

  it.effect(
    "bounds cold replay and exposes omitted native history without deleting persisted records",
    () =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          fake.session.getEvents = async () =>
            Array.from({ length: 513 }, (_, index) => durablePhase(`phase-${index}`));
          const { emitted, takeEvent } = yield* setup(fake, "native-copilot");
          yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.kind === "gap",
          );
          const phases = emitted.filter(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.kind === "phase",
          );
          assert.equal(phases.length, 512);
          assert.isTrue(
            emitted.some(
              (event) =>
                event.type === "turn_item.updated" &&
                event.turnItem.type === "system_notice" &&
                event.turnItem.modelExecution?.gaps.some((gap) => gap.startsWith("1 older native")),
            ),
          );
        }),
      ),
  );
  it.effect(
    "creates, resumes and switches plain Auto turns without optional routing-tier metadata",
    () =>
      provide(
        Effect.gen(function* () {
          const autoSelection: ModelSelection = { instanceId, model: "auto" };
          for (const resumed of [undefined, "native-copilot"]) {
            const fake = fakeSdk();
            fake.setCurrent({ modelId: "auto" });
            const { start, drain } = yield* setup(fake, resumed, autoSelection);
            assert.equal(fake.config.model, "auto");
            assert.isUndefined(fake.config.capi);
            yield* start();
            assert.equal(fake.sent.length, 1);
            fake.emit("session.idle");
            yield* drain();
            yield* start(2, selection);
            fake.emit("session.idle");
            yield* drain();
            yield* start(3, autoSelection);
            assert.equal(fake.sent.length, 3);
            assert.deepEqual(
              fake.modelChanges.map((change) => change.model),
              ["auto", "gpt-4.1", "auto"],
            );
            assert.isTrue(
              fake.modelChanges.every((change) => change.options?.autoTier === undefined),
            );
            fake.emit("session.idle");
            yield* drain();
          }
        }),
      ),
  );

  it.effect(
    "preserves opaque create/resume routing and distinguishes pending, applied and failed activation",
    () =>
      provide(
        Effect.gen(function* () {
          const auto = {
            defaultTier: "standard",
            tiers: ["standard", "fuse@2026:opaque"].map((id) => ({
              id,
              displayName: id,
              description: "",
              type: "auto",
              status: { enabled: true },
            })),
          };
          const autoSelection: ModelSelection = {
            instanceId,
            model: "auto",
            options: [{ id: "autoTier", value: "fuse@2026:opaque" }],
          };
          for (const resumed of [undefined, "native-copilot"]) {
            const fake = fakeSdk();
            fake.setCatalog({ models: [], auto });
            fake.setCurrent({
              modelId: "auto",
              autoTier: "standard",
              pendingAutoTier: "fuse@2026:opaque",
            });
            const { start, drain, emitted, takeEvent } = yield* setup(fake, resumed, autoSelection);
            assert.deepEqual(fake.config.capi, { autoTier: "fuse@2026:opaque" });
            yield* start();
            assert.deepEqual(fake.modelChanges[0], {
              model: "auto",
              options: { autoTier: "fuse@2026:opaque" },
            });
            const pending = yield* takeEvent(
              (event) =>
                event.type === "turn_item.updated" &&
                event.turnItem.runId === RunId.make("run-1") &&
                event.turnItem.type === "system_notice" &&
                event.turnItem.modelExecution?.status === "pending",
            );
            assert.equal(pending.type, "turn_item.updated");
            if (pending.type !== "turn_item.updated" || pending.turnItem.type !== "system_notice")
              return assert.fail("Expected persisted routing state.");
            assert.equal(pending.turnItem.modelExecution?.effectivePreference, "standard");
            assert.equal(pending.turnItem.modelExecution?.requestedPreference, "fuse@2026:opaque");
            fake.setCurrent({ modelId: "auto", autoTier: "fuse@2026:opaque" });
            fake.emit("session.model_change", {});
            yield* takeEvent(
              (event) =>
                event.type === "turn_item.updated" &&
                event.turnItem.type === "system_notice" &&
                event.turnItem.modelExecution?.status === "effective",
            );
            fake.setCurrent({ modelId: "auto", autoTier: "standard" });
            fake.emit("session.auto_tier_switch_failed", {
              requestedAutoTier: "fuse@2026:opaque",
              effectiveAutoTier: "standard",
              reason: "policy-changed",
            });
            yield* takeEvent(
              (event) =>
                event.type === "turn_item.updated" &&
                event.turnItem.type === "system_notice" &&
                event.turnItem.modelExecution?.status === "activation-failed",
            );
            const states = emitted.flatMap((event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution
                ? [event.turnItem.modelExecution]
                : [],
            );
            assert.isTrue(
              states.some(
                (state) =>
                  state.status === "effective" && state.effectivePreference === "fuse@2026:opaque",
              ),
            );
            assert.isTrue(
              states.some(
                (state) =>
                  state.status === "activation-failed" && state.effectivePreference === "standard",
              ),
            );
            fake.emit("session.idle");
            yield* drain();
            yield* start(2, selection);
            assert.equal(fake.modelChanges.at(-1)?.model, "gpt-4.1");
            assert.deepEqual(fake.modelChanges.at(-1)?.options, {});
          }
        }),
      ),
  );

  it.effect(
    "keeps phase identity and late ownership without finishing the root or counting aggregate usage",
    () =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const { start, drain, emitted, takeEvent } = yield* setup(fake);
          yield* start();
          fake.emit("assistant.turn_start", { turnId: "0" });
          fake.emit("session.fusion_resolved", {
            fusionId: "fusion-1",
            turnId: "0",
            contractVersion: 1,
            pattern: "critique",
            primaryModel: "same-model",
            secondaryModel: "same-model",
            fallbackModel: "fallback",
            syntheticModel: "auto",
          });
          for (const phaseId of ["draft", "critic"])
            fake.emit("assistant.fusion_phase_started", {
              fusionId: "fusion-1",
              phaseId,
              model: "same-model",
              role: phaseId,
              pattern: "critique",
            });
          fake.emit("assistant.fusion_phase_completed", {
            fusionId: "fusion-1",
            phaseId: "critic",
            model: "same-model",
            role: "critic",
            durationMs: 2000,
            status: "completed",
            content: "PRIVATE CRITIC",
            usage: { inputTokens: 500 },
          });
          fake.emit("session.fusion_completed", {
            fusionId: "fusion-1",
            turnId: "0",
            pattern: "critique",
            durationMs: 2000,
            outcome: "completed",
            finalSourceModel: "same-model",
            finalSourcePhaseId: "draft",
            awaitingBackgroundWork: true,
            syntheticModel: "auto",
            inputTokens: 1000,
          });
          assert.equal((yield* drain()).providerTurns[0]?.status, "running");
          assert.isUndefined((yield* drain()).providerTurns[0]?.tokenUsage);
          fake.emit("assistant.usage", { inputTokens: 10, outputTokens: 5 });
          assert.equal((yield* drain()).providerTurns[0]?.tokenUsage?.usedTokens, 15);
          fake.emit("session.idle");
          assert.equal((yield* drain()).providerTurns[0]?.status, "completed");
          yield* start(2);
          fake.emit("assistant.fusion_phase_completed", {
            fusionId: "fusion-1",
            phaseId: "draft",
            model: "same-model",
            role: "draft",
            durationMs: 2500,
            status: "completed",
            content: "PRIVATE DRAFT",
          });
          fake.emit("assistant.fusion_phase_failed", {
            fusionId: "unknown-fusion",
            phaseId: "late",
            model: "same-model",
            role: "critic",
            durationMs: 100,
            status: "failed",
            reason: "cancelled",
            errorMessage: "PRIVATE ERROR",
          });
          yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.fusionId === "unknown-fusion",
          );
          const items = new Map(
            emitted.flatMap((event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution
                ? [[event.turnItem.id, event.turnItem] as const]
                : [],
            ),
          );
          const phases = [...items.values()].filter(
            (item) => item.modelExecution?.kind === "phase",
          );
          assert.equal(phases.length, 3);
          assert.isTrue(
            phases
              .filter((item) => item.modelExecution?.fusionId === "fusion-1")
              .every((item) => item.runId === RunId.make("run-1")),
          );
          assert.equal(
            phases.find((item) => item.modelExecution?.fusionId === "unknown-fusion")?.runId,
            null,
          );
          assert.notInclude(JSON.stringify([...items.values()]), "PRIVATE");
        }),
      ),
  );

  it.effect(
    "imports cold native execution history with stable IDs and honest missing associations",
    () =>
      provide(
        Effect.gen(function* () {
          const ids: string[] = [];
          for (let restart = 0; restart < 2; restart++) {
            const fake = fakeSdk();
            fake.session.getEvents = async () => [durablePhase("primary")];
            const { takeEvent } = yield* setup(
              fake,
              "native-copilot",
              selection,
              ProviderSessionId.make(`restart-${restart}`),
            );
            const imported = yield* takeEvent((event) => event.type === "turn_item.updated");
            if (imported.type !== "turn_item.updated" || imported.turnItem.type !== "system_notice")
              return assert.fail("Expected imported execution history.");
            ids.push(imported.turnItem.id);
            assert.equal(imported.turnItem.runId, null);
            assert.equal(imported.turnItem.modelExecution?.startSource, "estimated");
            assert.include(
              imported.turnItem.modelExecution?.gaps.join(" "),
              "could not be associated",
            );
          }
          assert.equal(ids[0], ids[1]);
        }),
      ),
  );
  it.effect(
    "waits for the native permission receipt and never replaces V2-owned response delivery",
    () =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const { runtime, start, drain, emitted, takeEvent } = yield* setup(fake);
          yield* start();
          const permission = {
            kind: "read" as const,
            path: "/workspace/data",
            intention: "Read input",
          };
          fake.emit("permission.requested", {
            requestId: "native-permission",
            permissionRequest: permission,
          });
          const snapshot = yield* drain();
          assert.equal(snapshot.runtimeRequests.length, 1);
          const request = snapshot.runtimeRequests[0]!;
          assert.equal(request.nativeRequestRef?.nativeId, "native-permission");
          yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "approval_request" &&
              event.turnItem.requestId === request.id,
          );
          const called = promiseGate();
          const receipt = promiseGate();
          fake.setPermissionResponse(async () => {
            called.resolve();
            await receipt.promise;
            return { success: true };
          });
          const observedBeforeReply = emitted.length;
          const replying = yield* Effect.forkChild(
            runtime.respondToRuntimeRequest({ requestId: request.id, decision: "accept" }),
          );
          yield* Effect.promise(() => called.promise);
          assert.isUndefined(replying.pollUnsafe());
          receipt.resolve();
          yield* Fiber.join(replying);
          fake.emit("assistant.message", {
            messageId: "reply-boundary",
            content: "Receipt delivered",
          });
          yield* takeEvent((event) => event.type === "message.updated");
          assert.equal(
            emitted
              .slice(observedBeforeReply)
              .filter(
                (event) =>
                  event.type === "runtime_request.updated" ||
                  event.type === "node.updated" ||
                  (event.type === "turn_item.updated" &&
                    event.turnItem.type === "approval_request"),
              ).length,
            0,
          );
          assert.deepEqual(fake.permissionReplies, [
            { requestId: "native-permission", result: { kind: "approve-once" } },
          ]);
          assert.equal((yield* drain()).runtimeRequests.length, 0);
          yield* runtime.respondToRuntimeRequest({ requestId: request.id, decision: "accept" });
          assert.equal(fake.permissionReplies.length, 1);
          assert.isTrue(
            Exit.isFailure(
              yield* runtime
                .respondToRuntimeRequest({ requestId: request.id, decision: "decline" })
                .pipe(Effect.exit),
            ),
          );
        }),
      ),
  );

  it.effect.each(["applied", "already-resolved", "transport-error"] as const)(
